def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    z = (g == 0)
    best = None
    for y0 in range(H):
        for x0 in range(W):
            for y1 in range(y0 + 1, H):
                for x1 in range(x0 + 1, W):
                    if z[y0:y1+1, x0:x1+1].all():
                        a = (y1 - y0 + 1) * (x1 - x0 + 1)
                        if best is None or a > best[0]:
                            best = (a, y0, x0, y1, x1)
    out = g.copy()
    if best:
        _, y0, x0, y1, x1 = best
        out[y0:y1+1, x0:x1+1] = 6
    emit(out, "Fill the largest all-zero rectangle (at least 2x2) with colour 6.")
    return out
